        if (String(expandedRef || '') !== String(item.branch)) return;
        if ((item.labels || []).indexOf('validation_failed') !== -1) return; // already parked
        var cap = triggerFailuresModule.capOf(RUN_JOB_PARAMS);
        if (cap <= 0) return;
        var bodies = [];
        try {
